ALTER TABLE classrooms ADD COLUMN capacity integer CHECK(capacity>0), ADD COLUMN caregiver_ratio integer CHECK(caregiver_ratio>0);
ALTER TABLE idempotency_keys ADD COLUMN authorization_context text;
ALTER TABLE records DROP CONSTRAINT records_kind_check;
ALTER TABLE records ADD CONSTRAINT records_kind_check CHECK(kind IN ('settings','care-instruction','shift','attendance','pickup-authorization','pickup','activity','media','handoff','incident','incident-update','announcement','message','lead','lead-event','tour','trial','followup','enrollment','consent','data-request','camera-link','camera-policy','camera-session','analytics-ref','ai-query','ai-draft','fee-plan','invoice','payment','payment-event','subscription','usage','report','retention-job','job-run','support-access','integration-status','morning-note','daily-story','daily-closing','passport','passport-change','observation','development-report','development-rubric','whatsapp-draft'));
CREATE INDEX record_batch ON records(organization_id,(data->>'batchId')) WHERE kind='activity';
CREATE UNIQUE INDEX pickup_checkin_once ON records(organization_id,(data->>'checkInId')) WHERE kind='pickup' AND data ? 'checkInId';
CREATE UNIQUE INDEX daily_story_once ON records(organization_id,child_id,(data->>'date')) WHERE kind='daily-story';
CREATE UNIQUE INDEX current_passport ON records(organization_id,child_id) WHERE kind='passport';
CREATE FUNCTION app_capability(cap text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT app_role()='owner' OR (app_role()='manager' AND coalesce((SELECT CASE WHEN cap='finance' THEN (data->>'managerFinance')::boolean WHEN cap='crm' THEN (data->>'managerCrm')::boolean ELSE false END FROM records WHERE organization_id=app_org() AND kind='settings' ORDER BY updated_at DESC LIMIT 1),false)) $$;
CREATE FUNCTION care_policy() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT jsonb_build_object('routinePublishing',coalesce(data->>'routinePublishing','caregiver'),'substituteReview',coalesce((data->>'substituteReview')::boolean,true)) FROM records WHERE organization_id=app_org() AND kind='settings' ORDER BY updated_at DESC LIMIT 1),'{}'::jsonb)||jsonb_build_object('role',app_role()) $$;
CREATE FUNCTION can_manage_record(k text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT app_role()='owner' OR (app_role()='manager' AND CASE WHEN k IN ('invoice','payment','payment-event','fee-plan') THEN app_capability('finance') WHEN k IN ('lead','lead-event','tour','trial','followup','enrollment','whatsapp-draft') THEN app_capability('crm') WHEN k IN ('settings','subscription','support-access','retention-job','camera-link','camera-policy','usage','integration-status') THEN false ELSE true END) $$;
CREATE OR REPLACE FUNCTION can_record(k text,child uuid,s text,actor uuid,payload jsonb) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT can_manage_record(k) OR (app_role()='manager' AND k='development-rubric') OR (app_role()='caregiver' AND ((child IS NOT NULL AND can_child(child) AND k IN ('activity','attendance','media','pickup-authorization','pickup','care-instruction','incident','incident-update','message','ai-draft','morning-note','daily-story','passport','passport-change','observation','development-report')) OR k='development-rubric' OR (k='handoff' AND (actor=app_user() OR payload->>'recipientId'=app_user()::text)) OR (k='shift' AND payload->>'userId'=app_user()::text))) OR (app_role()='parent' AND ((child IS NOT NULL AND can_child(child) AND ((k IN ('activity','media','daily-story','development-report') AND s='published') OR k IN ('attendance','pickup-authorization','pickup','invoice','passport') OR (k IN ('consent','data-request','message','morning-note','passport-change') AND actor=app_user()) OR (k='message' AND (payload->>'recipientId'=app_user()::text OR payload->>'audience'='guardians')) OR (k='incident-update' AND s='published' AND payload->>'parentVisible'='true'))) OR (k='announcement' AND s='published'))) $$;
DROP POLICY records_insert ON records;
CREATE POLICY records_insert ON records FOR INSERT WITH CHECK(organization_id=app_org() AND created_by=app_user() AND ((can_manage_record(kind) AND kind<>'consent') OR (app_role()='caregiver' AND ((child_id IS NOT NULL AND can_child(child_id) AND kind IN ('activity','attendance','media','incident','incident-update','message','ai-draft','pickup','daily-story','observation')) OR kind='handoff')) OR (app_role()='parent' AND state IN ('draft','submitted','requested','approved') AND child_id IS NOT NULL AND can_child(child_id) AND kind IN ('message','consent','data-request','pickup-authorization','morning-note','passport-change'))));
DROP POLICY records_update ON records;
CREATE POLICY records_update ON records FOR UPDATE USING(organization_id=app_org() AND (can_manage_record(kind) OR (app_role()='caregiver' AND can_child(child_id) AND ((created_by=app_user() AND kind IN ('activity','media','ai-draft','daily-story','observation')) OR kind='morning-note')) OR (app_role()='caregiver' AND kind='handoff' AND data->>'recipientId'=app_user()::text) OR (app_role()='parent' AND can_child(child_id) AND created_by=app_user() AND kind IN ('consent','morning-note','pickup-authorization')))) WITH CHECK(organization_id=app_org());
CREATE FUNCTION actor_label(target uuid,target_child uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN can_child(target_child) THEN (SELECT nullif(display_name,'') FROM memberships WHERE organization_id=app_org() AND user_id=target AND active) ELSE NULL END $$;
CREATE POLICY pickup_mark_used ON records FOR UPDATE USING(organization_id=app_org() AND app_role()='caregiver' AND kind='pickup-authorization' AND state='approved' AND can_child(child_id)) WITH CHECK(organization_id=app_org() AND app_role()='caregiver' AND kind='pickup-authorization' AND state='used' AND can_child(child_id));
CREATE FUNCTION media_consent(target_child uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT can_child(target_child) AND EXISTS(SELECT 1 FROM records r JOIN guardian_child_links g ON g.organization_id=r.organization_id AND g.child_id=r.child_id AND g.user_id=r.created_by JOIN memberships m ON m.organization_id=g.organization_id AND m.user_id=g.user_id WHERE r.organization_id=app_org() AND r.child_id=target_child AND r.kind='consent' AND r.data->>'scope'='media' AND r.data->>'granted'='true' AND r.state<>'revoked' AND g.revoked_at IS NULL AND m.active AND m.role='parent') $$;
REVOKE ALL ON FUNCTION app_capability(text),care_policy(),actor_label(uuid,uuid),media_consent(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_capability(text),care_policy(),can_manage_record(text),actor_label(uuid,uuid),media_consent(uuid) TO daylio_app;
